import java.util.*;

class Solution {
    public int trifib(int n) {
        // base cases
        if (n == 0 || n == 1) {
            return 0;
        }
        if (n == 2) {
            return 1;
        }

        int[] dp = new int[n+1];

        // initializing the base cases in array
        dp[0] = 0;
        dp[1] = 0;
        dp[2] = 1;

        for(int i = 3; i <= n; i++) {
            dp[i] = dp[i-1] + dp[i-2] + 2* dp[i-3];
        }

        return dp[n];
    }
